'use client';

import React from 'react';
import { motion } from 'motion/react';
import Image from 'next/image';
import { Swords, Gamepad2, Tv } from 'lucide-react';

import ufcImg from '../../../assets/ufc.png';
import ffImg from '../../../assets/freefire.png';
import wsImg from '../../../assets/webseries.png';

const BeyondCode = () => {
    const interests = [
        {
            title: "UFC Enthusiast",
            description: "Nothing beats the adrenaline of a main event fight night. I'm deep into the technique, the discipline, and the sheer grit of MMA.",
            image: ufcImg,
            icon: <Swords className="w-5 h-5" />,
            color: "from-red-600/20 to-zinc-900/40",
            accent: "text-red-500",
            border: "border-red-500/20"
        },
        {
            title: "Free Fire Survivor",
            description: "When I'm not coding, I'm usually in the Booyah zone. Strategy, fast reflexes, and clearing the lobby is my way of unwinding.",
            image: ffImg,
            icon: <Gamepad2 className="w-5 h-5" />,
            color: "from-cyan-600/20 to-zinc-900/40",
            accent: "text-cyan-500",
            border: "border-cyan-500/20"
        },
        {
            title: "Cinephile & Series",
            description: "I love getting lost in complex narratives and cinematic storytelling. It's where I find inspiration for visual rhythm and pacing.",
            image: wsImg,
            icon: <Tv className="w-5 h-5" />,
            color: "from-purple-600/20 to-zinc-900/40",
            accent: "text-purple-500",
            border: "border-purple-500/20"
        }
    ];

    const containerVariants = {
        hidden: { opacity: 0 },
        visible: {
            opacity: 1,
            transition: { staggerChildren: 0.2 }
        }
    };

    const itemVariants = {
        hidden: { opacity: 0, y: 30, filter: 'blur(10px)' },
        visible: {
            opacity: 1,
            y: 0,
            filter: 'blur(0px)',
            transition: { duration: 0.8, ease: [0.22, 1, 0.36, 1] }
        }
    };

    return (
        <section className="space-y-12 py-10">
            {/* Header */}
            <motion.div
                initial={{ opacity: 0, x: -20 }}
                whileInView={{ opacity: 1, x: 0 }}
                viewport={{ once: true }}
                className="space-y-2 border-b border-black/5 dark:border-white/5 pb-8"
            >
                <span className="text-[9px] font-mono tracking-[0.3em] uppercase text-gray-400 block">
                    Interests
                </span>
                <h2 className="text-4xl md:text-5xl font-instrument italic font-normal text-gray-900 dark:text-white tracking-tight">
                    Beyond <span className="font-inter not-italic font-light text-gray-500 dark:text-gray-400 text-3xl md:text-4xl">the Screen</span>
                </h2>
            </motion.div>

            {/* Grid */}
            <motion.div
                variants={containerVariants}
                initial="hidden"
                whileInView="visible"
                viewport={{ once: true }}
                className="grid grid-cols-1 md:grid-cols-3 gap-6"
            >
                {interests.map((interest, index) => (
                    <motion.div
                        key={interest.title}
                        variants={itemVariants}
                        className="group relative h-112.5 rounded-3xl overflow-hidden border border-black/5 dark:border-white/5 bg-zinc-50 dark:bg-zinc-900/50"
                    >
                        {/* Background Image */}
                        <div className="absolute inset-0 transition-transform duration-700 group-hover:scale-110">
                            <Image
                                src={interest.image}
                                alt={interest.title}
                                fill
                                className="object-cover opacity-60 grayscale-[0.5] group-hover:grayscale-0 transition-all duration-700"
                            />
                            <div className={`absolute inset-0 bg-linear-to-t ${interest.color} via-zinc-950/80 to-zinc-950`} />
                        </div>

                        {/* Content */}
                        <div className="relative h-full p-8 flex flex-col justify-end space-y-4">
                            <div className={`w-10 h-10 rounded-xl flex items-center justify-center bg-black/20 backdrop-blur-md border ${interest.border} ${interest.accent}`}>
                                {interest.icon}
                            </div>
                            <div className="space-y-2">
                                <h3 className="text-2xl font-instrument italic text-white leading-tight">
                                    {interest.title}
                                </h3>
                                <p className="text-sm font-inter font-light text-zinc-400 leading-relaxed opacity-0 group-hover:opacity-100 transition-opacity duration-500 transform translate-y-4 group-hover:translate-y-0">
                                    {interest.description}
                                </p>
                            </div>
                        </div>

                        {/* Hover Overlay Light */}
                        <div className="absolute inset-0 opacity-0 group-hover:opacity-100 transition-opacity duration-500 pointer-events-none">
                            <div className={`absolute inset-0 bg-linear-to-tr ${interest.accent.replace('text-', 'from-')}/10 to-transparent`} />
                        </div>
                    </motion.div>
                ))}
            </motion.div>
        </section>
    );
};

export default BeyondCode;